<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { Server, UserRound, Radio, Check, RefreshCw, ExternalLink, Info } from 'lucide-vue-next'
import { useWorkspace } from '../stores/workspace'
import { apiUrl, validateBase } from '../api'
const store = useWorkspace(); const form = reactive({ ...store.settings }); const testing = ref(false); const tested = ref<boolean>(); const baseError = computed(() => validateBase(form.apiBase)); const userError = computed(() => !form.userId.trim() ? '请输入用户 ID' : form.userId.length > 64 ? '用户 ID 不能超过 64 个字符' : '')
const changed = computed(() => JSON.stringify(form) !== JSON.stringify(store.settings))
async function test() { if (baseError.value) return; testing.value = true; tested.value = await store.checkConnection(form.apiBase); testing.value = false; store.notify(tested.value ? '连接成功，服务健康检查正常' : `连接失败：${store.connectionError}`) }
function save() { if (baseError.value || userError.value || store.busy) return; store.settings = { ...form, apiBase: form.apiBase.replace(/\/+$/, ''), userId: form.userId.trim() }; store.notify('设置已保存，新会话将使用这些设置'); store.checkConnection() }
</script>
<template><div class="page settings-page"><div class="page-heading"><div><div class="eyebrow">PREFERENCES</div><h1>工作空间设置</h1><p>配置服务连接与你的对话偏好。</p></div></div><section class="settings-section"><div class="settings-description"><span class="small-icon"><Server :size="18" /></span><h2>服务连接</h2><p>连接本地或已部署的 Adaptive-RAG 后端。</p></div><div class="card settings-form"><label for="api-base">API 基础地址</label><input id="api-base" v-model.trim="form.apiBase" :aria-invalid="!!baseError" :class="{ invalid: baseError }" placeholder="/api/v1" @input="tested = undefined" /><span v-if="baseError" class="error-text">{{ baseError }}</span><p class="field-help">默认 /api/v1 通过开发代理连接本机 8000 端口。跨域直连需要后端允许 CORS。</p><div class="test-row"><button class="button" :disabled="!!baseError || testing" @click="test"><RefreshCw v-if="testing" class="spin" :size="15" /><Radio v-else :size="15" />{{ testing ? '测试连接中…' : '测试连接' }}</button><span v-if="tested !== undefined" class="badge" :class="tested ? 'success' : 'warning'">{{ tested ? '服务可用' : '连接失败' }}</span><a v-if="!baseError" class="text-button" :href="apiUrl(form.apiBase, '/health')" target="_blank" rel="noopener noreferrer">健康检查<ExternalLink :size="13" /></a></div><div v-if="testing" class="skeleton-lines"><div /><div /></div><p v-if="tested === false" class="error-text">{{ store.connectionError }}。请确认后端已启动且地址正确。</p></div></section><section class="settings-section"><div class="settings-description"><span class="small-icon"><UserRound :size="18" /></span><h2>对话偏好</h2><p>身份和响应方式将应用于新请求。</p></div><div class="card settings-form"><label for="user-id">用户 ID</label><input id="user-id" v-model="form.userId" :aria-invalid="!!userError" :class="{ invalid: userError }" placeholder="u_demo" /><span v-if="userError" class="error-text">{{ userError }}</span><p class="field-help">用于后端业务查询。已有会话保留创建时的用户 ID 与 API 地址；这不是身份认证。</p><div class="toggle-row"><div><strong>流式回答</strong><p class="field-help">逐步接收回答内容。</p></div><button class="toggle" :class="{ on: form.stream }" role="switch" :aria-checked="form.stream" aria-label="启用流式回答" @click="form.stream = !form.stream"><span /></button></div></div></section><div class="settings-save"><span>{{ store.busy ? '请求处理中，暂时无法保存' : changed ? '你有尚未保存的更改' : '设置已同步至本地' }}</span><button class="button primary" :disabled="!!baseError || !!userError || !changed || store.busy" @click="save"><Check :size="16" />保存设置</button></div><div class="settings-info"><Info :size="18" /><p>会话和设置保存在当前浏览器。清除浏览器数据会移除本地记录；后端的订单与物流数据取决于服务端配置。</p></div></div></template>
